function qiIcon(name, size) {
  const s = size || 18;
  return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${QI_ICONS[name] || ''}</svg>`;
}

function qiEsc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Animated villa. Driven by the house: day/night from sun.sun, lit windows from the
// configured lights, the front door glows when unlocked, a ring pulses round the
// house when the alarm is armed, and the camera dots blink while cameras are live.
// --p keeps every animation in phase across re-renders (all cycles divide 60s).
function qiVilla(o) {
  const win = (pts, i) => {
    const lit = i < o.litWindows;
    return `<g class="win ${lit ? 'lit' : ''}">
      ${lit ? `<polygon class="halo" points="${pts}" filter="url(#qi-glow)" style="animation-delay:calc(var(--p) - ${i * 2}s)"/>` : ''}
      <polygon class="pane" points="${pts}"/>
    </g>`;
  };
  const windows = [
    '182.1,137 234,167 234,207 182.1,177',
    '260,182 312,212 312,252 260,222',
    '212.4,77.5 273,112.5 273,137.5 212.4,102.5',
    '407,165 425,154.6 425,184.6 407,195',
    '330,92 346,82.8 346,104.8 330,114',
  ].map(win).join('');
  const stars = [[70,40],[140,22],[430,30],[500,70],[40,120],[380,12],[250,18],[560,110],[20,60],[330,8],[180,60],[470,8]]
    .map(([x,y],i) => `<circle class="star" cx="${x}" cy="${y}" r="${1 + (i % 3) * 0.4}" style="animation-delay:calc(var(--p) - ${(i * 0.7) % 3}s)"/>`).join('');
  const ring = o.alarm === 'triggered' ? 'ring alarm-hot' : (o.alarm === 'armed' ? 'ring alarm-on' : 'ring');
  return `
<svg class="villa ${o.night ? 'night' : 'day'} ${o.doorOpen ? 'door-open' : ''} ${o.camsLive ? 'cams' : ''}" viewBox="0 0 560 330" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${qiEsc(o.label)}" style="--p:-${Date.now() % 60000}ms">
  <defs>
    <filter id="qi-glow" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="7"/></filter>
    <filter id="qi-soft" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="14"/></filter>
    <clipPath id="qi-pool"><polygon points="430,230 494,267 451,292 386,255"/></clipPath>
    <clipPath id="qi-house"><polygon points="156.1,110 329.3,210 329.3,270 156.1,170"/><polygon points="433.2,150 329.3,210 329.3,270 433.2,210"/><polygon points="260,50 433.2,150 329.3,210 156.1,110"/><polygon points="199.4,60 286,110 286,155 199.4,105"/><polygon points="355.3,70 286,110 286,155 355.3,115"/><polygon points="268.7,20 355.3,70 286,110 199.4,60"/></clipPath>
    <linearGradient id="qi-sheen" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#FFFFFF" stop-opacity="0"/><stop offset="0.5" stop-color="#FFFFFF" stop-opacity="0.35"/><stop offset="1" stop-color="#FFFFFF" stop-opacity="0"/></linearGradient>
    <radialGradient id="qi-spill" cx="0.5" cy="0.5" r="0.5"><stop offset="0" stop-color="#F6D58A" stop-opacity="0.75"/><stop offset="1" stop-color="#F6D58A" stop-opacity="0"/></radialGradient>
  </defs>
  <g class="sky-night">${stars}
    <g class="meteor" style="animation-delay:calc(var(--p) - 3s)"><path d="M0 0 L46 20" stroke="#F7F4ED" stroke-width="1.6" stroke-linecap="round"/></g>
    <g class="meteor late" style="animation-delay:calc(var(--p) - 7s)"><path d="M0 0 L34 15" stroke="#F7F4ED" stroke-width="1.2" stroke-linecap="round"/></g>
    <circle cx="512" cy="38" r="11" fill="#F7F4ED" opacity="0.92"/><circle cx="517" cy="34" r="10" fill="#0C2418"/>
  </g>
  <g class="sky-day">
    <circle class="sun-halo" cx="508" cy="44" r="26" fill="#F6D58A" filter="url(#qi-soft)"/>
    <circle cx="508" cy="44" r="13" fill="#F6D58A"/>
    <g class="cloud" style="animation-delay:calc(var(--p))"><ellipse cx="80" cy="50" rx="34" ry="9" fill="#F7F4ED" opacity="0.18"/><ellipse cx="100" cy="43" rx="20" ry="8" fill="#F7F4ED" opacity="0.18"/></g>
    <g class="cloud slow" style="animation-delay:calc(var(--p) - 30s)"><ellipse cx="300" cy="24" rx="40" ry="8" fill="#F7F4ED" opacity="0.14"/></g>
  </g>
  <ellipse class="shadow" cx="320" cy="275" rx="230" ry="45" fill="#061409" opacity="0.8" style="animation-delay:var(--p)"/>
  <ellipse class="${ring}" cx="300" cy="235" rx="215" ry="72"/>
  <circle class="patrol" r="3.2"><animateMotion dur="12s" repeatCount="indefinite" begin="-${(Date.now() % 12000) / 1000}s" path="M85,235 a215,72 0 1,0 430,0 a215,72 0 1,0 -430,0"/></circle>
  <g class="float" style="animation-delay:var(--p)">
  <ellipse class="spill" cx="392" cy="262" rx="44" ry="16" fill="url(#qi-spill)"/>
  <polygon points="424.5,225 502.4,270 450.4,300 372.5,255" fill="#1F6E7A"/>
  <polygon points="430,230 494,267 451,292 386,255" fill="#4FC3C9" opacity="0.55"/>
  <g clip-path="url(#qi-pool)">
    <g class="ripples" style="animation-delay:calc(var(--p))">
      <path d="M380 248 L470 300 M396 238 L486 290 M412 228 L502 280" stroke="#DFF7F7" stroke-width="1.6" opacity="0.35" stroke-dasharray="10 14"/>
    </g>
  </g>
  <polygon points="156.1,110 329.3,210 329.3,270 156.1,170" fill="#E9E4D8"/>
  <polygon points="433.2,150 329.3,210 329.3,270 433.2,210" fill="#CFC8B8"/>
  <polygon points="260,50 433.2,150 329.3,210 156.1,110" fill="#F7F4ED"/>
  <polygon points="199.4,60 286,110 286,155 199.4,105" fill="#E9E4D8"/>
  <polygon points="355.3,70 286,110 286,155 355.3,115" fill="#CFC8B8"/>
  <polygon points="268.7,20 355.3,70 286,110 199.4,60" fill="#FBF9F4"/>
  <g clip-path="url(#qi-house)"><rect class="sheen" x="60" y="0" width="70" height="320" fill="url(#qi-sheen)" style="animation-delay:var(--p)"/></g>
  ${windows}
  <g class="door">
    <polygon class="door-glow" points="389.9,195 363.9,210 363.9,250 389.9,235" filter="url(#qi-glow)"/>
    <polygon class="door-leaf" points="389.9,195 363.9,210 363.9,250 389.9,235"/>
    <circle class="door-lock" cx="368.5" cy="229" r="2.2"/>
  </g>
  <circle class="cam-dot" cx="334" cy="207" r="2.4" style="animation-delay:calc(var(--p))"/>
  <circle class="cam-dot" cx="160" cy="113" r="2.4" style="animation-delay:calc(var(--p) - 1s)"/>
  ${[0, 1.33, 2.66].map((d) => `<circle class="wave" cx="277" cy="52" r="14" style="animation-delay:calc(var(--p) - ${d}s)"/>`).join('')}
  </g>
  ${[[150,230,0],[210,250,1.5],[260,285,3],[330,295,4.5],[420,240,6],[480,215,7.5],[110,215,9],[380,300,10.5],[300,240,2.2],[455,285,8.2]]
    .map(([x,y,d]) => `<circle class="fly" cx="${x}" cy="${y}" r="1.8" style="animation-delay:calc(var(--p) - ${d}s)"/>`).join('')}
  <g class="tree" style="animation-delay:calc(var(--p))"><circle cx="120" cy="190" r="16" fill="#1E4A30"/><circle cx="104" cy="200" r="11" fill="#2B5E3E"/></g>
  <g class="tree" style="animation-delay:calc(var(--p) - 2s)"><circle cx="470" cy="190" r="12" fill="#1E4A30"/></g>
</svg>`;
}

