const QI_STYLE = `
:host { display:block; height:100%; }
* { box-sizing:border-box; }
button { font-family:inherit; cursor:pointer; -webkit-tap-highlight-color:transparent; }
.app { --bg:#08190F; --card:#0F2B1F; --card2:#0C2418; --raised:#12331F; --line:rgba(247,244,237,0.07);
  --text:#F7F4ED; --muted:#A9BFB1; --warm:#F4D27A; --armed:#F2A27A; --armed-ink:#3A1405; --ink:#0F2B1F;
  height:100vh; height:100dvh; background:var(--bg); color:var(--text);
  font-family:'DM Sans',system-ui,sans-serif; display:flex; flex-direction:column; gap:16px;
  padding:max(20px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
  overflow:hidden; }
.display { font-family:Sora,'DM Sans',sans-serif; }
.muted { color:var(--muted); }
.label { font-size:12px; font-weight:600; letter-spacing:1.4px; color:var(--muted); }
.card { background:var(--card); border:1px solid var(--line); border-radius:24px; }
.top { height:56px; flex:none; display:flex; align-items:center; justify-content:space-between; gap:16px; }
.top-left { display:flex; align-items:baseline; gap:14px; }
.clock { font-family:Sora,sans-serif; font-size:40px; font-weight:600; letter-spacing:-1px; line-height:1; }
.top-title { font-size:15px; font-weight:500; }
.top-sub { font-size:13px; color:var(--muted); }
.brand { font-family:Sora,sans-serif; font-size:22px; font-weight:600; letter-spacing:0.5px; display:flex; align-items:center; gap:8px; background:none; border:none; color:var(--text); padding:0; }
.brand-word { display:inline-flex; height:30px; width:99px; color:var(--text); }
.brand-word svg { width:100%; height:100%; }
.saver-mark { display:block; width:34px; height:36px; color:var(--accent); margin-bottom:6px; opacity:0.9; }
.saver-mark svg { width:100%; height:100%; }
.top-right { display:flex; align-items:center; gap:10px; }
.pill { height:40px; padding:0 16px; border-radius:20px; display:flex; align-items:center; gap:8px; background:var(--card); border:1px solid rgba(247,244,237,0.08); color:var(--text); font-size:14px; font-weight:500; }
.pill.armed { background:var(--armed); border-color:var(--armed); color:var(--armed-ink); font-weight:600; }
.pill.ghost { background:transparent; border-color:rgba(247,244,237,0.18); font-weight:600; height:44px; border-radius:22px; }
.body { flex:1; min-height:0; display:grid; gap:16px; }
.dock-wrap { flex:none; display:flex; justify-content:center; }
.dock { display:flex; gap:6px; padding:6px; border-radius:22px; background:var(--card); border:1px solid rgba(247,244,237,0.08); }
.dock button { height:48px; padding:0 18px; border-radius:16px; border:none; display:flex; align-items:center; gap:8px; font-size:14px; font-weight:600; background:transparent; color:var(--muted); }
.dock button.on { background:var(--accent); color:var(--ink); }
.btn { height:44px; padding:0 16px; border-radius:14px; border:none; font-size:14px; font-weight:600; background:rgba(247,244,237,0.08); color:var(--text); }
.btn.primary { background:var(--accent); color:var(--ink); }
.btn.outline { background:transparent; border:1px solid rgba(247,244,237,0.18); }
.btn[disabled] { opacity:0.4; cursor:default; }
.dot { width:7px; height:7px; border-radius:50%; display:inline-block; flex:none; }
.bar { flex:1; height:10px; border-radius:5px; background:rgba(247,244,237,0.12); overflow:hidden; }
.bar > div { height:100%; border-radius:5px; }
.empty { padding:16px; border-radius:16px; border:1px dashed rgba(247,244,237,0.16); color:var(--muted); font-size:14px; }

/* Home */
.home { grid-template-columns:360px minmax(0,1fr); }
.col { display:flex; flex-direction:column; gap:14px; min-height:0; }
.weather { height:140px; flex:none; padding:20px 22px; display:flex; flex-direction:column; justify-content:space-between; }
.weather-temp { font-family:Sora,sans-serif; font-size:52px; font-weight:600; letter-spacing:-2px; line-height:1; }
.tiles { flex:1; min-height:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); grid-template-rows:repeat(3,minmax(0,1fr)); gap:12px; }
.tile { text-align:left; padding:16px; border-radius:22px; background:var(--card); border:1px solid var(--line); color:var(--text); display:flex; flex-direction:column; justify-content:space-between; min-height:110px; }
.tile.alert { border-color:var(--armed); }
.tile-icon { width:38px; height:38px; border-radius:12px; display:flex; align-items:center; justify-content:center; }
.tile-value { font-family:Sora,sans-serif; font-size:clamp(18px, 2.1vw, 26px); font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:100%; display:block; }
.tile > span:last-child { min-width:0; max-width:100%; }
.tile-value small { font-size:16px; color:var(--muted); font-weight:600; }
.tile-label { font-size:13px; color:var(--muted); }
.hero { height:372px; flex:none; border-radius:26px; background:var(--card2); border:1px solid var(--line); display:flex; overflow:hidden; }
.hero-art { flex:1; min-width:0; position:relative; }
.hero-art svg { width:100%; height:100%; display:block; }
/* Villa animation */
.villa .sky-day, .villa .sky-night { transition:opacity 1.2s ease; }
.villa.day .sky-night, .villa.night .sky-day { opacity:0; }
.villa .star { fill:#F7F4ED; animation:qi-twinkle 3s ease-in-out infinite; }
.villa .sun-halo { opacity:0.45; animation:qi-breathe 6s ease-in-out infinite; animation-delay:var(--p); }
.villa .cloud { animation:qi-drift 60s linear infinite; }
.villa .cloud.slow { animation-duration:60s; }
.villa .win .pane { fill:#36483F; transition:fill 0.8s ease; }
.villa.day .win .pane { fill:#A9C4CC; }
.villa .win.lit .pane { fill:#F6D58A; }
.villa .win .halo { fill:#F6D58A; opacity:0.55; animation:qi-breathe 6s ease-in-out infinite; }
.villa.day .win .halo { opacity:0.25; }
.villa .door-leaf { fill:#5A3B22; transition:fill 0.6s ease; }
.villa .door-glow { fill:#F6D58A; opacity:0; transition:opacity 0.6s ease; }
.villa .door-lock { fill:var(--accent); }
.villa.door-open .door-leaf { fill:#F6D58A; }
.villa.door-open .door-glow { opacity:0.8; animation:qi-breathe 4s ease-in-out infinite; animation-delay:var(--p); }
.villa.door-open .door-lock { fill:var(--warm); }
.villa .spill { opacity:0; transition:opacity 0.8s ease; }
.villa.door-open .spill { opacity:1; }
.villa .ripples { animation:qi-ripple 4s linear infinite; }
.villa .ring { fill:none; stroke:transparent; stroke-width:2; }
.villa .ring.alarm-on { stroke:var(--armed); stroke-dasharray:6 10; opacity:0.85; animation:qi-ring 20s linear infinite, qi-breathe 4s ease-in-out infinite; animation-delay:var(--p); }
.villa .ring.alarm-hot { stroke:#FF5A4A; stroke-width:3; animation:qi-hot 1s ease-in-out infinite; }
.villa .cam-dot { fill:#FF6B5A; opacity:0; }
.villa.cams .cam-dot { animation:qi-blink 2s steps(1) infinite; }
.villa .tree { transform-box:fill-box; transform-origin:50% 100%; animation:qi-sway 6s ease-in-out infinite; }
.villa .float { animation:qi-float 6s ease-in-out infinite; }
.villa .shadow { transform-box:fill-box; transform-origin:center; animation:qi-shadow 6s ease-in-out infinite; }
.villa .sheen { animation:qi-sheen 10s ease-in-out infinite; }
.villa .wave { fill:none; stroke:var(--accent); stroke-width:1.5; transform-box:fill-box; transform-origin:center; opacity:0; animation:qi-wave 4s ease-out infinite; }
.villa .fly { fill:var(--accent); opacity:0; animation:qi-fly 12s ease-in-out infinite; }
.villa.night .fly { fill:#F6D58A; }
.villa .patrol { fill:var(--accent); opacity:0.55; }
.villa .ring.alarm-on ~ .patrol { fill:var(--armed); opacity:1; }
.villa .meteor { opacity:0; animation:qi-meteor 10s linear infinite; }
.villa .meteor.late { animation-duration:12s; }
@keyframes qi-float { 0%,100% { transform:translateY(0); } 50% { transform:translateY(-7px); } }
@keyframes qi-shadow { 0%,100% { transform:scale(1); opacity:0.8; } 50% { transform:scale(0.95); opacity:0.6; } }
@keyframes qi-sheen { 0% { transform:translateX(0); } 60%,100% { transform:translateX(420px); } }
@keyframes qi-wave { 0% { transform:scale(0.3); opacity:0.9; } 100% { transform:scale(2.6); opacity:0; } }
@keyframes qi-fly { 0% { transform:translate(0,0); opacity:0; } 20% { opacity:0.9; } 50% { transform:translate(14px,-40px); opacity:0.6; } 80% { opacity:0.8; } 100% { transform:translate(-6px,-80px); opacity:0; } }
@keyframes qi-meteor { 0% { transform:translate(30px,20px); opacity:0; } 2% { opacity:1; } 12% { transform:translate(250px,118px); opacity:0; } 100% { transform:translate(250px,118px); opacity:0; } }
@keyframes qi-twinkle { 0%,100% { opacity:0.25; } 50% { opacity:0.95; } }
@keyframes qi-breathe { 0%,100% { opacity:0.45; } 50% { opacity:0.9; } }
@keyframes qi-drift { from { transform:translateX(-140px); } to { transform:translateX(620px); } }
@keyframes qi-ripple { from { transform:translate(-24px,-14px); } to { transform:translate(0,0); } }
@keyframes qi-ring { to { stroke-dashoffset:-320; } }
@keyframes qi-hot { 0%,100% { opacity:0.3; } 50% { opacity:1; } }
@keyframes qi-blink { 0% { opacity:0.95; } 50% { opacity:0.15; } }
@keyframes qi-sway { 0%,100% { transform:rotate(-1.5deg); } 50% { transform:rotate(1.5deg); } }
@media (prefers-reduced-motion: reduce) { .villa *, .villa, .saver-inner { animation:none !important; transition:none !important; } }
/* Screensaver */
.saver { position:fixed; inset:0; z-index:10; background:radial-gradient(ellipse at 50% 60%, #0F2B1F 0%, #061409 75%); color:var(--text); display:flex; align-items:center; justify-content:center; overflow:hidden; cursor:pointer; }
.saver-inner { width:min(1100px, 94vw); display:flex; flex-direction:column; align-items:center; gap:4px; animation:qi-drift-saver 60s ease-in-out infinite; }
.saver-clock { font-family:Sora,sans-serif; font-size:clamp(60px, min(11vw, 15vh), 140px); font-weight:600; letter-spacing:-4px; line-height:1; }
.saver-date { font-size:clamp(16px, 2.2vw, 24px); color:var(--muted); }
.saver-art { width:100%; height:min(46vh, 460px); margin-top:4px; }
.saver-art svg { width:100%; height:100%; display:block; }
.saver-status { display:flex; gap:10px; flex-wrap:wrap; justify-content:center; }
.saver-hint { margin-top:14px; font-size:13px; color:var(--muted); opacity:0.7; }
@keyframes qi-drift-saver { 0%,100% { transform:translate(0,0); } 25% { transform:translate(-24px,10px); } 50% { transform:translate(10px,-14px); } 75% { transform:translate(22px,8px); } }
.hero-greet { position:absolute; left:20px; top:18px; display:flex; flex-direction:column; gap:4px; }
.chips { position:absolute; left:20px; bottom:18px; right:20px; display:flex; gap:8px; flex-wrap:wrap; }
.chip { height:32px; padding:0 12px; border-radius:16px; background:rgba(8,25,15,0.85); border:1px solid rgba(247,244,237,0.1); display:flex; align-items:center; gap:6px; font-size:13px; font-weight:500; }
.access { width:248px; flex:none; padding:18px; border-left:1px solid var(--line); display:flex; flex-direction:column; gap:12px; }
.access-item { padding:14px; border-radius:18px; background:var(--card); display:flex; flex-direction:column; gap:10px; }
.row { display:flex; justify-content:space-between; align-items:center; gap:10px; }
.ring { text-align:left; padding:12px 14px; border-radius:18px; background:transparent; border:1px dashed rgba(247,244,237,0.16); color:var(--text); display:flex; align-items:center; gap:10px; }
.bottom { flex:1; min-height:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px; }
.scenes { padding:18px; display:flex; flex-direction:column; gap:12px; }
.scene-grid { flex:1; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
.scene { border-radius:16px; font-size:15px; font-weight:600; border:1px solid rgba(247,244,237,0.1); background:var(--raised); color:var(--text); min-height:52px; }
.scene.on { background:var(--accent); color:var(--ink); }
.media { padding:18px; display:flex; flex-direction:column; gap:12px; }
.art { width:64px; height:64px; border-radius:14px; background:#1E4A30; display:flex; align-items:center; justify-content:center; color:var(--accent); flex:none; background-size:cover; background-position:center; }
.round { width:52px; height:52px; border-radius:50%; border:none; background:var(--accent); color:var(--ink); display:flex; align-items:center; justify-content:center; flex:none; }
.small-round { width:44px; height:44px; border-radius:12px; border:none; background:rgba(247,244,237,0.08); color:var(--text); font-size:20px; font-weight:600; flex:none; }

/* Security */
.security { grid-template-columns:minmax(0,1fr) 360px; }
.live { flex:1; min-height:0; border-radius:26px; background:#0A1F14; border:1px solid var(--line); position:relative; overflow:hidden; display:flex; align-items:center; justify-content:center; }
.live img { width:100%; height:100%; object-fit:cover; display:block; }
.live-ph { display:flex; flex-direction:column; align-items:center; gap:10px; color:rgba(247,244,237,0.25); font-size:14px; }
.live-top { position:absolute; left:18px; top:16px; display:flex; align-items:center; gap:10px; }
.live-bottom { position:absolute; left:18px; right:18px; bottom:16px; display:flex; justify-content:space-between; align-items:center; gap:12px; }
.badge { height:30px; padding:0 12px; border-radius:15px; background:rgba(8,25,15,0.85); display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; letter-spacing:1px; color:var(--text); }
.live-name { font-family:Sora,sans-serif; font-size:20px; font-weight:600; text-shadow:0 1px 6px rgba(0,0,0,0.6); }
.thumbs { height:118px; flex:none; display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:10px; }
.thumb { position:relative; border-radius:16px; background:#0A1F14; color:var(--text); padding:0; overflow:hidden; border:2px solid transparent; }
.thumb.on { border-color:var(--accent); }
.thumb img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.thumb span { position:absolute; left:8px; bottom:6px; right:8px; font-size:12px; font-weight:600; text-align:left; text-shadow:0 1px 4px rgba(0,0,0,0.8); }
.modes { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; }
.mode { height:64px; border-radius:16px; border:1px solid rgba(247,244,237,0.1); font-size:14px; font-weight:600; background:var(--raised); color:var(--text); }
.mode.on { background:var(--accent); color:var(--ink); }
.mode.on.armed { background:var(--armed); color:var(--armed-ink); }
.warn { padding:10px 12px; border-radius:12px; background:#3A2A0C; color:#F6D58A; font-size:13px; line-height:1.35; }
.zone { min-height:34px; display:flex; justify-content:space-between; align-items:center; font-size:14px; gap:10px; }
.zone .open { color:#F6D58A; font-weight:600; }

/* Cameras */
.cams { grid-template-columns:repeat(3,minmax(0,1fr)); grid-template-rows:repeat(2,minmax(0,1fr)); gap:12px; }
.cam { position:relative; border-radius:22px; background:#0A1F14; border:1px solid var(--line); color:var(--text); padding:0; overflow:hidden; }
.cam img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.cam .badge { position:absolute; left:14px; top:12px; height:26px; font-size:11px; }
.cam-foot { position:absolute; left:14px; right:14px; bottom:12px; display:flex; justify-content:space-between; align-items:center; text-shadow:0 1px 6px rgba(0,0,0,0.7); }
.cam-focus { grid-template-columns:1fr; grid-template-rows:minmax(0,1fr) 64px; gap:12px; }
.strip { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:8px; }
.strip button { border-radius:14px; background:var(--card); color:var(--text); font-size:13px; font-weight:600; border:2px solid transparent; }
.strip button.on { border-color:var(--accent); }

/* Lights */
.lights { grid-template-columns:290px minmax(0,1fr); }
.rooms { padding:14px; display:flex; flex-direction:column; gap:6px; overflow:auto; }
.room { min-height:56px; padding:0 14px; border-radius:14px; border:none; display:flex; justify-content:space-between; align-items:center; text-align:left; background:transparent; color:var(--text); flex:none; }
.room.on { background:var(--accent); color:var(--ink); }
.room .count { font-size:12px; color:var(--muted); }
.room .count.lit { color:var(--warm); }
.room.on .count { color:var(--ink); }
.room-panel { padding:20px 22px; border-radius:24px; background:var(--card2); border:1px solid var(--line); display:flex; flex-direction:column; gap:16px; overflow:auto; }
.light-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.light { padding:14px 16px; border-radius:18px; display:flex; flex-direction:column; gap:12px; background:var(--card); border:1px solid rgba(247,244,237,0.06); }
.light.lit { background:#1A3A22; border-color:rgba(244,210,122,0.35); }
.switch { width:56px; height:32px; border-radius:16px; border:none; padding:3px; display:flex; justify-content:flex-start; background:rgba(247,244,237,0.18); flex:none; }
.switch.on { justify-content:flex-end; background:var(--accent); }
.switch span { width:26px; height:26px; border-radius:50%; background:#F7F4ED; }
.shutter { padding:12px 16px; border-radius:18px; background:var(--card); display:flex; align-items:center; gap:16px; }
.shutter-name { width:160px; display:flex; flex-direction:column; gap:2px; flex:none; }

@media (max-width: 960px) {
  .app { height:auto; min-height:100vh; overflow:visible; padding:16px; }
  .body, .home, .security, .lights, .bottom { grid-template-columns:1fr; }
  .hero { flex-direction:column; height:auto; }
  .hero-art { height:280px; }
  .access { width:auto; border-left:none; border-top:1px solid var(--line); }
  .cams { grid-template-columns:repeat(2,minmax(0,1fr)); grid-template-rows:none; grid-auto-rows:180px; }
  .live { min-height:260px; }
  .thumbs, .strip { grid-template-columns:repeat(3,minmax(0,1fr)); height:auto; grid-auto-rows:80px; }
  .light-grid { grid-template-columns:1fr; }
  .shutter { flex-wrap:wrap; }
  .brand { display:none; }
  .dock { flex-wrap:wrap; justify-content:center; }
  .dock button { padding:0 12px; }
}
`;

class QuintecaPanel extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._view = 'home';
    this._room = 0;
    this._camFocus = -1;
    this._secCam = 0;
    this._sig = '';
    this._timers = [];
    this._onClick = this._onClick.bind(this);
    this._onTouch = this._onTouch.bind(this);
    this._saver = false;
  }

  /* ---------- Home Assistant hooks ---------- */
  set hass(hass) {
    this._hass = hass;
    const sig = this._signature();
    if (sig !== this._sig) {
      this._sig = sig;
      this._schedule();
    }
  }
  get hass() { return this._hass; }
  set panel(panel) { this._panel = panel; this._cfg = null; this._applySidebar(); this._schedule(); }

  // Wall panels: hide Home Assistant's sidebar on this device (same as the profile's
  // "Always hide the sidebar" setting). Tapping the Quinteca wordmark still opens the menu.
  _applySidebar() {
    if (this._sidebarDone || !this._panel || !this.isConnected) return;
    if (this.cfg.hideSidebar !== true) return;
    this._sidebarDone = true;
    this.dispatchEvent(new CustomEvent('hass-dock-sidebar', { detail: { dock: 'always_hidden' }, bubbles: true, composed: true }));
  }
  set narrow(v) { this._narrow = v; }
  set route(v) { this._route = v; }

  connectedCallback() {
    this._applySidebar();
    if (!document.querySelector('link[data-quinteca-fonts]')) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = QI_FONT_URL;
      link.setAttribute('data-quinteca-fonts', '');
      document.head.appendChild(link);
    }
    this.shadowRoot.addEventListener('click', this._onClick);
    this.shadowRoot.addEventListener('pointerdown', this._onTouch, true);
    this._lastTouch = Date.now();
    this._timers.push(setInterval(() => this._checkIdle(), 10000));
    this._timers.push(setInterval(() => this._tickClock(), 15000));
    this._timers.push(setInterval(() => this._refreshSnapshots(), 4000));
    this._schedule();
  }

  disconnectedCallback() {
    this.shadowRoot.removeEventListener('click', this._onClick);
    this.shadowRoot.removeEventListener('pointerdown', this._onTouch, true);
    this._timers.forEach((t) => clearInterval(t));
    this._timers = [];
  }

  /* ---------- config + state helpers ---------- */
  get cfg() {
    if (!this._cfg) {
      const user = (this._panel && this._panel.config) || {};
      this._cfg = Object.assign({}, QUINTECA_DEFAULTS, user);
    }
    return this._cfg;
  }

  _st(id) { return id && this._hass && this._hass.states ? this._hass.states[id] : undefined; }
  _attr(id, key) { const s = this._st(id); return s && s.attributes ? s.attributes[key] : undefined; }
  _name(id, fallback) {
    const n = this._attr(id, 'friendly_name');
    return fallback || n || (id ? id.split('.').pop().replace(/_/g, ' ') : '');
  }
  _domain(id) { return id ? id.split('.')[0] : ''; }
  _ok(id) { const s = this._st(id); return !!s && s.state !== 'unavailable' && s.state !== 'unknown'; }
  _call(domain, service, data) {
    if (!this._hass) return;
    this._hass.callService(domain, service, data || {}).catch((err) => {
      console.error('Quinteca panel', domain, service, err);
    });
  }

  _list(key) { const v = this.cfg[key]; return Array.isArray(v) ? v : []; }
  _camList() {
    return this._list('cameras').slice(0, 6).map((c) => (typeof c === 'string' ? { entity: c } : c));
  }
  _zoneList() { return this._list('zones').map((z) => (typeof z === 'string' ? { entity: z } : z)); }
  _sceneList() { return this._list('scenes').slice(0, 4).map((s) => (typeof s === 'string' ? { entity: s } : s)); }
  _rooms() {
    return this._list('rooms').map((r) => ({
      name: r.name || 'Room',
      lights: Array.isArray(r.lights) ? r.lights : [],
      covers: Array.isArray(r.covers) ? r.covers : [],
    }));
  }
  _allLights() { return this._rooms().reduce((a, r) => a.concat(r.lights), []); }
  _allCovers() { return this._rooms().reduce((a, r) => a.concat(r.covers), []); }

  _watched() {
    const c = this.cfg;
    const ids = [c.sun, c.weather, c.alarm, c.gate, c.frontDoor, c.doorbell, c.climate, c.mediaPlayer, c.wifiClients, c.internet];
    this._zoneList().forEach((z) => ids.push(z.entity));
    this._sceneList().forEach((s) => ids.push(s.entity));
    this._camList().forEach((cam) => ids.push(cam.entity));
    this._rooms().forEach((r) => { r.lights.forEach((l) => ids.push(l)); r.covers.forEach((x) => ids.push(x)); });
    return ids.filter(Boolean);
  }

  _signature() {
    if (!this._hass) return '';
    // Camera entities refresh their token every few minutes; only their state matters here.
    const cams = new Set(this._camList().map((x) => x.entity));
    return this._watched().map((id) => {
      const s = this._st(id);
      if (!s) return id + ':-';
      return id + ':' + (cams.has(id) ? s.state : s.last_updated);
    }).join('|');
  }

  _schedule() {
    if (this._raf) return;
    this._raf = requestAnimationFrame(() => { this._raf = null; this._render(); });
  }

  /* ---------- derived values ---------- */
  _lightOn(id) { const s = this._st(id); return !!s && s.state === 'on'; }
  _dimmable(id) {
    const modes = this._attr(id, 'supported_color_modes');
    if (Array.isArray(modes)) return !(modes.length === 1 && modes[0] === 'onoff');
    return this._attr(id, 'brightness') != null;
  }
  _brightPct(id) {
    const b = this._attr(id, 'brightness');
    return b == null ? (this._lightOn(id) ? 100 : 0) : Math.round(b / 2.55);
  }
  _coverPos(id) {
    const p = this._attr(id, 'current_position');
    if (typeof p === 'number') return p;
    const s = this._st(id);
    return s && (s.state === 'open' || s.state === 'opening') ? 100 : 0;
  }
  _coverCanSet(id) { return ((this._attr(id, 'supported_features') || 0) & 4) === 4; }

  _accessInfo(id) {
    const s = this._st(id);
    const d = this._domain(id);
    if (!s) return { word: 'not set up', open: false, action: null, ok: false };
    const st = s.state;
    if (d === 'lock') {
      const open = st === 'unlocked' || st === 'open' || st === 'unlocking' || st === 'opening';
      return { word: open ? 'unlocked' : (st === 'jammed' ? 'jammed' : 'locked'), open, action: open ? 'Lock' : 'Unlock', ok: true };
    }
    if (d === 'cover') {
      const open = st === 'open' || st === 'opening';
      return { word: st, open, action: open ? 'Close' : 'Open', ok: true };
    }
    if (d === 'button' || d === 'script' || d === 'scene') {
      return { word: 'ready', open: false, action: 'Open', ok: true };
    }
    const open = st === 'on' || st === 'open';
    return { word: open ? 'open' : 'closed', open, action: open ? 'Close' : 'Open', ok: true };
  }

  _accessToggle(id) {
    const s = this._st(id);
    if (!s) return;
    const d = this._domain(id);
    const info = this._accessInfo(id);
    if (d === 'lock') this._call('lock', info.open ? 'lock' : 'unlock', { entity_id: id });
    else if (d === 'cover') this._call('cover', info.open ? 'close_cover' : 'open_cover', { entity_id: id });
    else if (d === 'button') this._call('button', 'press', { entity_id: id });
    else if (d === 'script' || d === 'scene') this._call(d, 'turn_on', { entity_id: id });
    else this._call('homeassistant', 'toggle', { entity_id: id });
  }

  _alarmState() {
    const s = this._st(this.cfg.alarm);
    return s ? s.state : null;
  }
  _alarmLabel() {
    const st = this._alarmState();
    const map = {
      disarmed: 'Disarmed', armed_away: 'Armed · Away', armed_home: 'Armed · Home', armed_night: 'Armed · Night',
      armed_vacation: 'Armed · Holiday', arming: 'Arming…', pending: 'Entry delay', triggered: 'ALARM', disarming: 'Disarming…',
    };
    return st ? (map[st] || st) : 'Alarm not set up';
  }
  _alarmArmed() { const st = this._alarmState(); return !!st && st !== 'disarmed' && st !== 'unavailable' && st !== 'unknown'; }

  _zoneOpen(id) { const s = this._st(id); return !!s && s.state === 'on'; }
  _zoneWord(id) {
    const s = this._st(id);
    if (!s) return 'Not set up';
    const dc = this._attr(id, 'device_class');
    const on = s.state === 'on';
    if (dc === 'motion' || dc === 'occupancy' || dc === 'presence') return on ? 'Motion' : 'Clear';
    if (dc === 'door' || dc === 'window' || dc === 'opening' || dc === 'garage_door') return on ? 'Open' : 'Closed';
    return on ? 'Active' : 'Clear';
  }

  _snapUrl(id) {
    const pic = this._attr(id, 'entity_picture');
    if (!pic) return '';
    return pic + (pic.indexOf('?') >= 0 ? '&' : '?') + '_=' + Date.now();
  }
  _liveUrl(id) {
    const tok = this._attr(id, 'access_token');
    return tok ? '/api/camera_proxy_stream/' + id + '?token=' + tok : this._snapUrl(id);
  }

  _time(iso) {
    if (!iso) return '';
    const d = new Date(iso);
    if (isNaN(d)) return '';
    return d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
  }

  /* ---------- shared chrome ---------- */
  _top(title, sub, right) {
    const now = new Date();
    const clock = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    return `
    <header class="top">
      <div class="top-left">
        <div class="clock" data-clock>${clock}</div>
        <div style="display:flex;flex-direction:column;gap:2px">
          <div class="top-title" ${title === null ? 'data-date' : ''}>${qiEsc(title === null ? this._dateText() : title)}</div>
          <div class="top-sub">${qiEsc(sub)}</div>
        </div>
      </div>
      <button class="brand" data-action="menu" aria-label="Quinteca, open menu"><span class="brand-word">${QI_WORDMARK}</span></button>
      <div class="top-right">${right || ''}</div>
    </header>`;
  }

  _dateText() {
    return new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
  }

  _alarmPill() {
    const armed = this._alarmArmed();
    return `<button class="pill ${armed ? 'armed' : ''}" data-action="nav" data-arg="security">${qiIcon('shield', 16)}${qiEsc(this._alarmLabel())}</button>`;
  }

  _dock() {
    const items = [['home', 'home', 'Home'], ['lights', 'bulb', 'Lights'], ['security', 'shield', 'Security'], ['cameras', 'camera', 'Cameras']];
    return `<nav class="dock-wrap"><div class="dock">${items.map(([v, ic, label]) =>
      `<button class="${this._view === v ? 'on' : ''}" data-action="nav" data-arg="${v}">${qiIcon(ic)}${label}</button>`).join('')}</div></nav>`;
  }

  /* ---------- views ---------- */
  _viewHome() {
    const c = this.cfg;
    const w = this._st(c.weather);
    const wa = (w && w.attributes) || {};
    const cond = w ? w.state : '';
    const condWord = { 'clear-night': 'Clear night', sunny: 'Sunny', cloudy: 'Cloudy', partlycloudy: 'Partly cloudy', rainy: 'Rain', pouring: 'Heavy rain', fog: 'Fog', windy: 'Windy', lightning: 'Storms', 'lightning-rainy': 'Storms', snowy: 'Snow' }[cond] || (cond ? cond.replace(/-/g, ' ') : 'Weather not set up');
    const condIcon = cond === 'clear-night' ? 'moon' : (cond === 'sunny' ? 'sun' : 'cloud');
    const temp = wa.temperature != null ? Math.round(wa.temperature) + '°' : '–';

    const lights = this._allLights();
    const lightsOn = lights.filter((l) => this._lightOn(l)).length;
    const covers = this._allCovers();
    const coversOpen = covers.filter((x) => this._coverPos(x) > 0).length;
    const clim = this._st(c.climate);
    const climTemp = clim && clim.attributes.current_temperature != null ? Math.round(clim.attributes.current_temperature) + '°' : '–';
    const climMode = clim ? (clim.state === 'off' ? 'Off' : clim.state.replace(/_/g, ' ')) : 'not set up';
    const cams = this._camList();
    const camsLive = cams.filter((x) => this._ok(x.entity)).length;
    const wifi = this._st(c.wifiClients);
    const armed = this._alarmArmed();

    const gate = this._accessInfo(c.gate);
    const door = this._accessInfo(c.frontDoor);
    const internet = this._st(c.internet);
    const internetChip = internet
      ? `<div class="chip"><span class="dot" style="background:var(--accent)"></span>Internet ${qiEsc(Math.round(Number(internet.state)) || internet.state)} ${qiEsc(internet.attributes.unit_of_measurement || '')}</div>`
      : '';
    const bell = this._st(c.doorbell);
    const bellTime = bell ? this._time(this._domain(c.doorbell) === 'event' ? bell.state : bell.last_changed) : '';

    const scenes = this._sceneList();
    let latest = -1; let latestT = 0;
    scenes.forEach((s, i) => { const st = this._st(s.entity); const t = st ? Date.parse(st.state) : NaN; if (!isNaN(t) && t > latestT) { latestT = t; latest = i; } });

    const mp = this._st(c.mediaPlayer);
    const ma = (mp && mp.attributes) || {};
    const playing = mp && mp.state === 'playing';
    const vol = ma.volume_level != null ? Math.round(ma.volume_level * 100) : null;

    const tile = (icon, bg, ink, value, label, nav, alert) => `
      <button class="tile ${alert ? 'alert' : ''}" data-action="nav" data-arg="${nav}">
        <span class="tile-icon" style="background:${bg};color:${ink}">${qiIcon(icon, 20)}</span>
        <span style="display:flex;flex-direction:column;gap:2px"><span class="tile-value">${value}</span><span class="tile-label">${qiEsc(label)}</span></span>
      </button>`;

    const villa = this._villa();
    const greet = c.greetingName ? `Good ${this._partOfDay()}, ${qiEsc(c.greetingName)}` : `Good ${this._partOfDay()}`;
    const anyOpenZone = this._zoneList().some((z) => this._zoneOpen(z.entity));

    return `
    ${this._top(null, c.homeName + ' · ' + c.location, this._alarmPill())}
    <main class="body home">
      <section class="col">
        <div class="card weather">
          <div class="row" style="align-items:flex-start">
            <div style="display:flex;flex-direction:column;gap:6px">${qiIcon(condIcon, 30)}<div style="font-size:15px;font-weight:500">${qiEsc(condWord)}</div></div>
            <div class="weather-temp">${temp}</div>
          </div>
          <div class="row muted" style="font-size:13px">
            <span>Humidity ${wa.humidity != null ? Math.round(wa.humidity) + '%' : '–'}</span>
            <span>Wind ${wa.wind_speed != null ? Math.round(wa.wind_speed) + ' ' + qiEsc(wa.wind_speed_unit || 'km/h') : '–'}</span>
          </div>
        </div>
        <div class="tiles">
          ${tile('bulb', '#F4D27A', '#2A1F05', `${lightsOn}<small> / ${lights.length}</small>`, 'Lights on', 'lights')}
          ${tile('shutter', '#9CC7E8', '#0B2233', `${coversOpen}<small> open</small>`, 'Shutters', 'lights')}
          ${tile('thermo', '#F2A27A', '#3A1405', climTemp, 'Climate · ' + climMode, 'home')}
          ${tile('shield', armed ? 'var(--armed)' : 'var(--accent)', '#0F2B1F', qiEsc(armed ? 'Armed' : (this._alarmState() ? 'Disarmed' : '–')), 'Alarm' + (anyOpenZone ? ' · zone open' : ''), 'security', armed)}
          ${tile('camera', '#C8B6F2', '#1E1236', `${camsLive}<small> live</small>`, 'Cameras', 'cameras')}
          ${tile('wifi', '#8FE0C2', '#06291C', wifi ? qiEsc(wifi.state) : 'OK', wifi ? 'WiFi devices' : 'Network', 'home')}
        </div>
      </section>
      <section class="col">
        <div class="hero">
          <div class="hero-art">
            ${villa}
            <div class="hero-greet"><div class="display" style="font-size:20px;font-weight:600">${greet}</div><div class="muted" style="font-size:13px">${armed ? 'The alarm is armed' : 'Everything is running normally'}</div></div>
            <div class="chips">
              <div class="chip"><span class="dot" style="background:${gate.open ? 'var(--warm)' : 'var(--accent)'}"></span>${qiEsc(c.gateName)} ${qiEsc(gate.word)}</div>
              <div class="chip"><span class="dot" style="background:${door.open ? 'var(--warm)' : 'var(--accent)'}"></span>${qiEsc(c.frontDoorName)} ${qiEsc(door.word)}</div>
              ${internetChip}
            </div>
          </div>
          <div class="access">
            <div class="label">ACCESS</div>
            <div class="access-item">
              <div class="row"><span style="font-size:15px;font-weight:600">${qiEsc(c.gateName)}</span><span class="muted" style="font-size:13px">${qiEsc(gate.word)}</span></div>
              <button class="btn primary" data-action="access" data-arg="gate" ${gate.ok ? '' : 'disabled'}>${qiEsc(gate.action || 'Not set up')}</button>
            </div>
            <div class="access-item">
              <div class="row"><span style="font-size:15px;font-weight:600">${qiEsc(c.frontDoorName)}</span><span class="muted" style="font-size:13px">${qiEsc(door.word)}</span></div>
              <button class="btn outline" data-action="access" data-arg="frontDoor" ${door.ok ? '' : 'disabled'}>${qiEsc(door.action || 'Not set up')}</button>
            </div>
            ${bell ? `<button class="ring" data-action="ring">${qiIcon('bell')}<span style="display:flex;flex-direction:column"><span style="font-size:14px;font-weight:600">Doorbell ${qiEsc(bellTime)}</span><span class="muted" style="font-size:12px">View gate camera</span></span></button>` : ''}
          </div>
        </div>
        <div class="bottom">
          <div class="card scenes">
            <div class="label">SCENES</div>
            ${scenes.length ? `<div class="scene-grid">${scenes.map((s, i) => `<button class="scene ${i === latest ? 'on' : ''}" data-action="scene" data-arg="${i}">${qiEsc(this._name(s.entity, s.name))}</button>`).join('')}</div>` : '<div class="empty">Add scenes in the panel config.</div>'}
          </div>
          <div class="card media">
            <div class="row"><span class="label">MUSIC</span><span class="muted" style="font-size:13px">${qiEsc(mp ? this._name(c.mediaPlayer) : 'Not set up')}</span></div>
            <div style="display:flex;align-items:center;gap:14px">
              <div class="art" ${ma.entity_picture ? `style="background-image:url('${qiEsc(ma.entity_picture)}')"` : ''}>${ma.entity_picture ? '' : qiIcon('music', 28)}</div>
              <div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:3px">
                <div style="font-size:16px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${qiEsc(ma.media_title || (mp ? (playing ? 'Playing' : 'Nothing playing') : '–'))}</div>
                <div class="muted" style="font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${qiEsc(ma.media_artist || ma.source || '')}</div>
              </div>
              <button class="round" data-action="playpause" aria-label="Play or pause" ${mp ? '' : 'disabled'}>${qiIcon(playing ? 'pause' : 'play', 20)}</button>
            </div>
            <div style="display:flex;align-items:center;gap:10px;margin-top:auto">
              <button class="small-round" data-action="vol" data-arg="-5" aria-label="Volume down" ${mp ? '' : 'disabled'}>−</button>
              <div class="bar"><div style="width:${vol || 0}%;background:var(--accent)"></div></div>
              <button class="small-round" data-action="vol" data-arg="5" aria-label="Volume up" ${mp ? '' : 'disabled'}>+</button>
            </div>
          </div>
        </div>
      </section>
    </main>`;
  }

  _villa() {
    const c = this.cfg;
    const lights = this._allLights();
    const lightsOn = lights.filter((l) => this._lightOn(l)).length;
    const sunSt = this._st(c.sun);
    const hr = new Date().getHours();
    const night = sunSt ? sunSt.state === 'below_horizon' : (hr < 7 || hr >= 20);
    const nWin = 5;
    const litWindows = lights.length ? Math.ceil((lightsOn / lights.length) * nWin) : (night ? nWin : 0);
    const door = this._accessInfo(c.frontDoor);
    const armed = this._alarmArmed();
    const alarmSt = this._alarmState();
    const camsLive = this._camList().filter((x) => this._ok(x.entity)).length;
    return qiVilla({
      night, litWindows, doorOpen: door.ok && door.open, camsLive,
      alarm: alarmSt === 'triggered' ? 'triggered' : (armed ? 'armed' : 'off'),
      label: `Illustration of ${c.homeName}: ${night ? 'night' : 'day'}, ${door.word || ''}${armed ? ', alarm armed' : ''}`,
    });
  }

  _viewSaver() {
    const c = this.cfg;
    const w = this._st(c.weather);
    const temp = w && w.attributes.temperature != null ? Math.round(w.attributes.temperature) + '°' : '';
    const door = this._accessInfo(c.frontDoor);
    const camsLive = this._camList().filter((x) => this._ok(x.entity)).length;
    const armed = this._alarmArmed();
    const chip = (dot, text) => `<div class="chip"><span class="dot" style="background:${dot}"></span>${qiEsc(text)}</div>`;
    return `
    <div class="saver" data-action="wake" role="button" aria-label="Tap to wake">
      <div class="saver-inner" style="animation-delay:-${Date.now() % 60000}ms">
        <span class="saver-mark">${QI_MARK}</span>
        <div class="saver-clock" data-clock>${new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}</div>
        <div class="saver-date"><span data-date>${qiEsc(this._dateText())}</span>${temp ? ' · ' + temp : ''}</div>
        <div class="saver-art">${this._villa()}</div>
        <div class="saver-status">
          ${this._alarmState() ? chip(armed ? 'var(--armed)' : 'var(--accent)', this._alarmLabel()) : ''}
          ${door.ok ? chip(door.open ? 'var(--warm)' : 'var(--accent)', c.frontDoorName + ' ' + door.word) : ''}
          ${camsLive ? chip('#FF6B5A', camsLive + (camsLive === 1 ? ' camera live' : ' cameras live')) : ''}
        </div>
        <div class="saver-hint">Tap anywhere to wake</div>
      </div>
    </div>`;
  }

  _partOfDay() {
    const h = new Date().getHours();
    return h < 12 ? 'morning' : (h < 18 ? 'afternoon' : 'evening');
  }

  _viewSecurity() {
    const c = this.cfg;
    const cams = this._camList();
    if (this._secCam >= cams.length) this._secCam = 0;
    const sel = cams[this._secCam];
    const st = this._alarmState();
    const armed = this._alarmArmed();
    const zones = this._zoneList();
    const openZones = zones.filter((z) => this._zoneOpen(z.entity) && ['door', 'window', 'opening', 'garage_door'].indexOf(this._attr(z.entity, 'device_class')) >= 0);
    const modes = [
      ['disarm', 'Disarmed', st === 'disarmed', false],
      ['night', 'Night', st === 'armed_night' || st === 'armed_home', true],
      ['away', 'Away', st === 'armed_away', true],
    ];
    const gateCam = sel && sel.gate;

    return `
    ${this._top('Security', c.homeName + ' · ' + c.location, this._alarmPill())}
    <main class="body security">
      <section class="col">
        <div class="live">
          ${sel && this._ok(sel.entity)
            ? `<img src="${qiEsc(this._liveUrl(sel.entity))}" alt="${qiEsc(this._name(sel.entity, sel.name))} live view">`
            : `<div class="live-ph">${qiIcon('camera', 56)}<span>${cams.length ? 'Camera offline' : 'Add cameras in the panel config'}</span></div>`}
          ${sel ? `<div class="live-top"><span class="badge"><span class="dot" style="background:#FF6B5A"></span>LIVE</span><span class="live-name">${qiEsc(this._name(sel.entity, sel.name))}</span></div>` : ''}
          ${sel ? `<div class="live-bottom"><span></span><div style="display:flex;gap:8px">
            <button class="btn" style="background:rgba(8,25,15,0.85)" data-action="nav" data-arg="cameras">All cameras</button>
            ${gateCam ? `<button class="btn primary" data-action="access" data-arg="gate">${qiEsc((this._accessInfo(c.gate).action || 'Open') + ' ' + String(c.gateName).toLowerCase())}</button>` : ''}
          </div></div>` : ''}
        </div>
        ${cams.length ? `<div class="thumbs">${cams.map((cam, i) => `
          <button class="thumb ${i === this._secCam ? 'on' : ''}" data-action="seccam" data-arg="${i}" aria-label="Show ${qiEsc(this._name(cam.entity, cam.name))}">
            ${this._ok(cam.entity) ? `<img data-snap="${qiEsc(cam.entity)}" src="${qiEsc(this._snapUrl(cam.entity))}" alt="">` : ''}
            <span>${qiEsc(this._name(cam.entity, cam.name))}</span>
          </button>`).join('')}</div>` : ''}
      </section>
      <section class="col">
        <div class="card" style="padding:18px;display:flex;flex-direction:column;gap:12px">
          <div class="row"><span class="label">ALARM</span><span class="muted" style="font-size:13px">${qiEsc(this._alarmLabel())}</span></div>
          <div class="modes">${modes.map(([arg, label, on, isArm]) =>
            `<button class="mode ${on ? 'on' : ''} ${isArm ? 'armed' : ''}" data-action="alarm" data-arg="${arg}" ${st ? '' : 'disabled'}>${label}</button>`).join('')}</div>
          ${openZones.length ? `<div class="warn">${qiEsc(openZones.map((z) => this._name(z.entity, z.name)).join(', '))} ${openZones.length === 1 ? 'is' : 'are'} open.${armed ? ' Check before leaving.' : ' Close before arming.'}</div>` : ''}
        </div>
        <div class="card" style="flex:1;min-height:0;overflow:auto;padding:16px 18px;display:flex;flex-direction:column;gap:4px">
          <div class="label" style="margin-bottom:6px">ZONES</div>
          ${zones.length ? zones.map((z) => {
            const open = this._zoneOpen(z.entity);
            return `<div class="zone"><span>${qiEsc(this._name(z.entity, z.name))}</span><span class="${open ? 'open' : 'muted'}">${qiEsc(this._zoneWord(z.entity))}</span></div>`;
          }).join('') : '<div class="empty">Add door, window and motion sensors in the panel config.</div>'}
        </div>
      </section>
    </main>`;
  }

  _viewCameras() {
    const c = this.cfg;
    const cams = this._camList();
    const live = cams.filter((x) => this._ok(x.entity)).length;
    const focused = this._camFocus >= 0 && this._camFocus < cams.length;
    const right = `${focused ? `<button class="pill ghost" data-action="camall">${qiIcon('grid', 16)}All cameras</button>` : ''}<div class="pill"><span class="dot" style="background:#FF6B5A"></span>${live} live</div>`;

    if (!cams.length) {
      return `${this._top('All cameras', c.homeName + ' · ' + c.location, right)}
      <main class="body"><div class="empty">Add up to six camera entities in the panel config.</div></main>`;
    }

    if (focused) {
      const cam = cams[this._camFocus];
      return `
      ${this._top('All cameras', c.homeName + ' · ' + c.location, right)}
      <main class="body cam-focus">
        <div class="live">
          ${this._ok(cam.entity) ? `<img src="${qiEsc(this._liveUrl(cam.entity))}" alt="${qiEsc(this._name(cam.entity, cam.name))} live view">` : `<div class="live-ph">${qiIcon('camera', 56)}<span>Camera offline</span></div>`}
          <div class="live-top"><span class="badge"><span class="dot" style="background:#FF6B5A"></span>LIVE</span><span class="live-name">${qiEsc(this._name(cam.entity, cam.name))}</span></div>
          <div class="live-bottom"><span></span><div style="display:flex;gap:8px">
            ${cam.gate ? `<button class="btn primary" data-action="access" data-arg="gate">${qiEsc((this._accessInfo(c.gate).action || 'Open') + ' ' + String(c.gateName).toLowerCase())}</button>` : ''}
          </div></div>
        </div>
        <div class="strip">${cams.map((x, i) => `<button class="${i === this._camFocus ? 'on' : ''}" data-action="camfocus" data-arg="${i}">${qiEsc(this._name(x.entity, x.name))}</button>`).join('')}</div>
      </main>`;
    }

    return `
    ${this._top('All cameras', c.homeName + ' · ' + c.location, right)}
    <main class="body cams">
      ${cams.map((cam, i) => `
        <button class="cam" data-action="camfocus" data-arg="${i}" aria-label="Open ${qiEsc(this._name(cam.entity, cam.name))}">
          ${this._ok(cam.entity) ? `<img data-snap="${qiEsc(cam.entity)}" src="${qiEsc(this._snapUrl(cam.entity))}" alt="">` : `<span class="live-ph" style="height:100%;justify-content:center">${qiIcon('camera', 40)}<span>Offline</span></span>`}
          <span class="badge"><span class="dot" style="background:${this._ok(cam.entity) ? '#FF6B5A' : '#777'}"></span>${this._ok(cam.entity) ? 'LIVE' : 'OFF'}</span>
          <span class="cam-foot"><span class="display" style="font-size:16px;font-weight:600">${qiEsc(this._name(cam.entity, cam.name))}</span></span>
        </button>`).join('')}
    </main>`;
  }

  _viewLights() {
    const c = this.cfg;
    const rooms = this._rooms();
    if (this._room >= rooms.length) this._room = 0;
    const lightsAll = this._allLights();
    const onAll = lightsAll.filter((l) => this._lightOn(l)).length;
    const coversOpen = this._allCovers().filter((x) => this._coverPos(x) > 0).length;
    const right = `<button class="pill ghost" data-action="alloff">All lights off</button><button class="pill ghost" data-action="closeall">Close all shutters</button>`;
    const sub = `${onAll} of ${lightsAll.length} lights on · ${coversOpen} shutters open`;

    if (!rooms.length) {
      return `${this._top('Lights & shutters', sub, right)}<main class="body"><div class="empty">Add rooms with their lights and covers in the panel config.</div></main>`;
    }
    const room = rooms[this._room];
    const roomOn = room.lights.filter((l) => this._lightOn(l)).length;

    return `
    ${this._top('Lights & shutters', sub, right)}
    <main class="body lights">
      <section class="card rooms">
        <div class="label" style="padding:4px 8px 6px">ROOMS</div>
        ${rooms.map((r, i) => {
          const n = r.lights.filter((l) => this._lightOn(l)).length;
          return `<button class="room ${i === this._room ? 'on' : ''}" data-action="room" data-arg="${i}"><span style="font-size:15px;font-weight:600">${qiEsc(r.name)}</span><span class="count ${n ? 'lit' : ''}">${n ? n + ' on' : 'Off'}</span></button>`;
        }).join('')}
      </section>
      <section class="room-panel">
        <div class="row">
          <div style="display:flex;flex-direction:column;gap:2px">
            <div class="display" style="font-size:26px;font-weight:600">${qiEsc(room.name)}</div>
            <div class="muted" style="font-size:13px">${roomOn} of ${room.lights.length} lights on${room.covers.length ? ' · ' + room.covers.length + ' shutters' : ''}</div>
          </div>
          ${room.lights.length ? `<button class="btn primary" data-action="roomtoggle">${roomOn ? 'Turn room off' : 'Turn room on'}</button>` : ''}
        </div>
        ${room.lights.length ? `<div class="label">LIGHTS</div><div class="light-grid">${room.lights.map((id) => {
          const on = this._lightOn(id);
          const dim = this._dimmable(id);
          const pct = this._brightPct(id);
          const sub = !this._st(id) ? 'Not found' : (dim ? (on ? 'Dimmer · ' + pct + '%' : 'Dimmer · off') : (on ? 'Switch · on' : 'Switch · off'));
          return `<div class="light ${on ? 'lit' : ''}">
            <div class="row"><div style="display:flex;flex-direction:column;gap:2px;min-width:0"><span style="font-size:15px;font-weight:600">${qiEsc(this._name(id))}</span><span class="muted" style="font-size:12px">${sub}</span></div>
              <button class="switch ${on ? 'on' : ''}" data-action="light" data-arg="${qiEsc(id)}" aria-label="Toggle ${qiEsc(this._name(id))}"><span></span></button></div>
            ${dim ? `<div style="display:flex;align-items:center;gap:10px">
              <button class="small-round" data-action="dim" data-arg="${qiEsc(id)}" data-step="-10" aria-label="Dim ${qiEsc(this._name(id))}">−</button>
              <div class="bar"><div style="width:${on ? pct : 0}%;background:var(--warm)"></div></div>
              <button class="small-round" data-action="dim" data-arg="${qiEsc(id)}" data-step="10" aria-label="Brighten ${qiEsc(this._name(id))}">+</button>
            </div>` : ''}
          </div>`;
        }).join('')}</div>` : ''}
        ${room.covers.length ? `<div class="label">SHUTTERS</div><div style="display:flex;flex-direction:column;gap:12px">${room.covers.map((id) => {
          const pos = this._coverPos(id);
          const word = !this._st(id) ? 'Not found' : (pos >= 100 ? 'Open' : (pos <= 0 ? 'Closed' : pos + '% open'));
          const canSet = this._coverCanSet(id);
          return `<div class="shutter">
            <div class="shutter-name"><span style="font-size:15px;font-weight:600">${qiEsc(this._name(id))}</span><span class="muted" style="font-size:12px">${word}</span></div>
            <div class="bar"><div style="width:${pos}%;background:#9CC7E8"></div></div>
            <div style="display:flex;gap:6px">
              <button class="btn" data-action="cover" data-arg="${qiEsc(id)}" data-pos="100">Open</button>
              ${canSet ? `<button class="btn" data-action="cover" data-arg="${qiEsc(id)}" data-pos="50">Half</button>` : `<button class="btn" data-action="coverstop" data-arg="${qiEsc(id)}">Stop</button>`}
              <button class="btn" data-action="cover" data-arg="${qiEsc(id)}" data-pos="0">Close</button>
            </div>
          </div>`;
        }).join('')}</div>` : ''}
      </section>
    </main>`;
  }

  /* ---------- render ---------- */
  _render() {
    if (!this.shadowRoot) return;
    const accent = /^#[0-9a-fA-F]{3,8}$/.test(this.cfg.accent || '') ? this.cfg.accent : '#CDF07E';
    let view = '';
    if (!this._hass) {
      view = '<div class="empty">Connecting to the house…</div>';
    } else if (this._saver) {
      this.shadowRoot.innerHTML = `<style>${QI_STYLE}</style><div class="app" style="--accent:${accent}">${this._viewSaver()}</div>`;
      return;
    } else if (this._view === 'security') view = this._viewSecurity();
    else if (this._view === 'cameras') view = this._viewCameras();
    else if (this._view === 'lights') view = this._viewLights();
    else view = this._viewHome();
    this.shadowRoot.innerHTML = `<style>${QI_STYLE}</style><div class="app" style="--accent:${accent}">${view}${this._hass ? this._dock() : ''}</div>`;
  }

  _tickClock() {
    const root = this.shadowRoot;
    if (!root) return;
    const clock = root.querySelector('[data-clock]');
    if (clock) clock.textContent = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    const date = root.querySelector('[data-date]');
    if (date) date.textContent = this._dateText();
  }

  _refreshSnapshots() {
    const root = this.shadowRoot;
    if (!root || !this._hass) return;
    root.querySelectorAll('img[data-snap]').forEach((img) => {
      const url = this._snapUrl(img.getAttribute('data-snap'));
      if (url) img.src = url;
    });
  }

  /* ---------- screensaver ---------- */
  _onTouch() {
    this._lastTouch = Date.now();
    if (this._saver) {
      this._saver = false;
      this._wokeAt = Date.now();
      this._render();
    }
  }

  _checkIdle() {
    const mins = Number(this.cfg.screensaverMinutes);
    if (this._saver || !this._hass || !(mins > 0)) return;
    // By default only wall tablets/phones get the screensaver, not a desktop browser.
    if (this.cfg.screensaverTouchOnly !== false && window.matchMedia && !window.matchMedia('(pointer: coarse)').matches) return;
    if (Date.now() - (this._lastTouch || 0) >= mins * 60000) {
      this._saver = true;
      this._render();
    }
  }

  /* ---------- actions ---------- */
  _onClick(ev) {
    if (this._wokeAt && Date.now() - this._wokeAt < 600) { this._wokeAt = 0; return; }
    const el = ev.target.closest('[data-action]');
    if (!el || el.disabled) return;
    const action = el.getAttribute('data-action');
    const arg = el.getAttribute('data-arg');
    const c = this.cfg;
    switch (action) {
      case 'menu':
        this.dispatchEvent(new Event('hass-toggle-menu', { bubbles: true, composed: true }));
        return;
      case 'nav':
        this._view = arg;
        if (arg === 'cameras') this._camFocus = -1;
        break;
      case 'access':
        this._accessToggle(c[arg]);
        return;
      case 'ring': {
        const cams = this._camList();
        const idx = cams.findIndex((x) => x.gate);
        this._view = 'cameras';
        this._camFocus = idx >= 0 ? idx : 0;
        break;
      }
      case 'scene': {
        const s = this._sceneList()[Number(arg)];
        if (s) this._call(this._domain(s.entity), 'turn_on', { entity_id: s.entity });
        return;
      }
      case 'playpause':
        this._call('media_player', 'media_play_pause', { entity_id: c.mediaPlayer });
        return;
      case 'vol': {
        const cur = this._attr(c.mediaPlayer, 'volume_level') || 0;
        const next = Math.max(0, Math.min(1, cur + Number(arg) / 100));
        this._call('media_player', 'volume_set', { entity_id: c.mediaPlayer, volume_level: Math.round(next * 100) / 100 });
        return;
      }
      case 'alarm': {
        const svc = { disarm: 'alarm_disarm', night: 'alarm_arm_night', away: 'alarm_arm_away' }[arg];
        if (!svc) return;
        const data = { entity_id: c.alarm };
        if (c.alarmCode) data.code = String(c.alarmCode);
        this._call('alarm_control_panel', svc, data);
        return;
      }
      case 'seccam':
        this._secCam = Number(arg);
        break;
      case 'camfocus':
        this._camFocus = Number(arg);
        break;
      case 'camall':
        this._camFocus = -1;
        break;
      case 'room':
        this._room = Number(arg);
        break;
      case 'roomtoggle': {
        const room = this._rooms()[this._room];
        if (!room) return;
        const anyOn = room.lights.some((l) => this._lightOn(l));
        if (room.lights.length) this._call('light', anyOn ? 'turn_off' : 'turn_on', { entity_id: room.lights });
        return;
      }
      case 'light':
        this._call('light', 'toggle', { entity_id: arg });
        return;
      case 'dim':
        this._call('light', 'turn_on', { entity_id: arg, brightness_step_pct: Number(el.getAttribute('data-step')) });
        return;
      case 'cover': {
        const pos = Number(el.getAttribute('data-pos'));
        if (this._coverCanSet(arg)) this._call('cover', 'set_cover_position', { entity_id: arg, position: pos });
        else this._call('cover', pos > 0 ? 'open_cover' : 'close_cover', { entity_id: arg });
        return;
      }
      case 'coverstop':
        this._call('cover', 'stop_cover', { entity_id: arg });
        return;
      case 'alloff': {
        const all = this._allLights();
        if (all.length) this._call('light', 'turn_off', { entity_id: all });
        return;
      }
      case 'closeall': {
        const all = this._allCovers();
        if (all.length) this._call('cover', 'close_cover', { entity_id: all });
        return;
      }
      default:
        return;
    }
    this._render();
  }
}

if (!customElements.get('quinteca-panel')) {
  customElements.define('quinteca-panel', QuintecaPanel);
}
